import React, { useMemo } from "react";
import { random } from "remotion";
import { palette } from "../theme/palette";

/*
 * Sky life for the wedding-day scenes: V-shaped birds and twinkling stars.
 * Drawn in scene (SVG user) space.
 */

/* ───────────────────────── sky life ───────────────────────── */

/** A flock of elegant V-shaped birds gliding across the sky; wings beat slowly then glide. */
export const Birds: React.FC<{ frame: number; x: number; y: number; dx?: number; dy?: number; count?: number; scale?: number; color?: string; seed?: string }> = ({
  frame,
  x,
  y,
  dx = 1.6,
  dy = -0.35,
  count = 5,
  scale = 1,
  color = palette.inkSoft,
  seed = "birds",
}) => {
  const birds = useMemo(
    () =>
      new Array(count).fill(0).map((_, i) => ({
        ox: (i % 2 ? -1 : 1) * Math.ceil(i / 2) * 46 + (random(`${seed}x${i}`) - 0.5) * 24 - Math.ceil(i / 2) * 20,
        oy: Math.ceil(i / 2) * 26 + (random(`${seed}y${i}`) - 0.5) * 18,
        s: (0.75 + random(`${seed}s${i}`) * 0.4) * scale,
        ph: random(`${seed}p${i}`) * Math.PI * 2,
      })),
    [count, seed, scale],
  );
  return (
    <g>
      {birds.map((b, i) => {
        const bx = x + b.ox + frame * dx;
        const by = y + b.oy + frame * dy + Math.sin(frame / 22 + b.ph) * 4;
        const flap = Math.sin(frame / 5 + b.ph);
        const lift = 4 + flap * 7;
        return (
          <path
            key={i}
            d={`M-16 ${-lift * 0.3} Q-8 ${-lift} 0 2 Q8 ${-lift} 16 ${-lift * 0.3}`}
            transform={`translate(${bx} ${by}) scale(${b.s})`}
            fill="none"
            stroke={color}
            strokeWidth={2.2}
            strokeLinecap="round"
            strokeLinejoin="round"
          />
        );
      })}
    </g>
  );
};

/** Four-point twinkling stars in an area; `show` 0→1 fades them in. */
export const Stars: React.FC<{ frame: number; show: number; area: [number, number, number, number]; count?: number; seed?: string; color?: string }> = ({
  frame,
  show,
  area,
  count = 30,
  seed = "stars",
  color = palette.goldPale,
}) => {
  const [ax, ay, aw, ah] = area;
  const pts = useMemo(
    () =>
      new Array(count).fill(0).map((_, i) => ({
        x: ax + random(`${seed}x${i}`) * aw,
        y: ay + random(`${seed}y${i}`) * ah,
        r: 1.4 + random(`${seed}r${i}`) * 3.2,
        p: random(`${seed}p${i}`) * Math.PI * 2,
        d: random(`${seed}d${i}`),
      })),
    [ax, ay, aw, ah, count, seed],
  );
  if (show <= 0) return null;
  return (
    <g>
      {pts.map((s, i) => {
        const appear = Math.min(1, Math.max(0, show * 1.6 - s.d * 0.6));
        const tw = 0.6 + 0.4 * Math.sin(frame / 18 + s.p);
        const r = s.r;
        return (
          <g key={i} opacity={appear * tw} transform={`translate(${s.x} ${s.y})`}>
            <circle r={r * 2.4} fill={color} opacity={0.15} />
            <path d={`M0 ${-r * 2.2} L${r * 0.45} 0 L0 ${r * 2.2} L${-r * 0.45} 0 Z M${-r * 2.2} 0 L0 ${r * 0.45} L${r * 2.2} 0 L0 ${-r * 0.45} Z`} fill={color} />
          </g>
        );
      })}
    </g>
  );
};
